  var waterPoint=TransportParameters.All.Single(p=>p.Key=="WATER_POINT");var jointSmoke=TransportParameters.All.Single(p=>p.Key=="PARTICLE_MOVEMENT_JOINT");check(!TransportParameters.Available(waterPoint,"$TYPE VEHICLETYPE_ROAD\n$END\n")&&TransportParameters.Available(waterPoint,"$TYPE VEHICLETYPE_ROAD\n$SKILL_FIRETRUCK 20\n$END\n")&&!TransportParameters.Available(jointSmoke,"$TYPE VEHICLETYPE_ROAD\n$END\n")&&TransportParameters.Available(jointSmoke,"$TYPE VEHICLETYPE_ROAD\n$PARTICLE_MOVEMENT_JOINT vehicle_medium 0 0 0\n$END\n"),"effect choices require a firetruck role or trailer while existing records remain repairable");
  var indicatorFrame=System.Numerics.Matrix4x4.CreateRotationY(MathF.PI/2);var indicatorPivot=new System.Numerics.Vector3(4,0,2);check(VehicleLights.IsLeft(new(1,0,0),System.Numerics.Vector3.Zero,System.Numerics.Matrix4x4.Identity)&&!VehicleLights.IsLeft(new(-1,0,0),System.Numerics.Vector3.Zero,System.Numerics.Matrix4x4.Identity)&&VehicleLights.IsLeft(indicatorPivot+System.Numerics.Vector3.TransformNormal(System.Numerics.Vector3.UnitX,indicatorFrame),indicatorPivot,indicatorFrame),"native positive-X left indicator stays on the left after moving and rotating the main pivot");
